const pedidoRow = $input.first()?.json;
const query = $('Webhook Confirmar').first().json.query || {};
const tokenInput = (query.token || '').trim();
const confirmarFlag = (query.confirmar || '').toLowerCase();

if (!pedidoRow || !pedidoRow.id) {
  return [{ json: { valido: false, motivo: 'pedido_no_encontrado', html: '<html><body style="font-family:sans-serif;padding:40px;text-align:center"><h2>❌ Pedido no encontrado</h2></body></html>' } }];
}
if (pedidoRow.token_db !== tokenInput) {
  return [{ json: { valido: false, motivo: 'token_invalido', html: '<html><body style="font-family:sans-serif;padding:40px;text-align:center"><h2>❌ Token inválido</h2></body></html>' } }];
}
if (pedidoRow.estado === 'pago_confirmado') {
  return [{ json: { valido: false, motivo: 'ya_confirmado', html: '<html><body style="font-family:sans-serif;padding:40px;text-align:center"><h2>✅ Este pedido ya fue confirmado</h2><p>Pedido WC #' + (pedidoRow.woo_order_id || pedidoRow.id) + ' del ' + pedidoRow.producto_nombre + '</p></body></html>' } }];
}
const estadosValidos = ['pendiente_admin_validar', 'pendiente_transferencia'];
if (!estadosValidos.includes(pedidoRow.estado)) {
  return [{ json: { valido: false, motivo: 'estado_invalido_' + pedidoRow.estado, html: '<html><body style="font-family:sans-serif;padding:40px;text-align:center"><h2>Estado inválido</h2><p>' + pedidoRow.estado + '</p></body></html>' } }];
}

if (confirmarFlag !== 'yes') {
  const baseUrl = ($env.N8N_WEBHOOK_BASE_URL || $env.WEBHOOK_URL || 'https://n8n.srv1398596.hstgr.cloud').replace(/\/$/, '');
  const confirmLink = baseUrl + '/webhook/savia/confirmar-transfer?id=' + pedidoRow.id + '&token=' + encodeURIComponent(tokenInput) + '&confirmar=yes';
  const totalDisplay = (pedidoRow.total_cop || 0).toLocaleString('es-CO');
  const html = '<html><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Confirmar pago</title></head>' +
    '<body style="font-family:sans-serif;padding:40px;max-width:600px;margin:0 auto;text-align:center;background:#fafafa">' +
    '<h2 style="color:#2e7d32">Confirmar pago recibido</h2>' +
    '<div style="background:white;padding:20px;border-radius:8px;text-align:left;margin:20px 0">' +
    '<p><strong>Pedido:</strong> ' + pedidoRow.producto_nombre + '</p>' +
    '<p><strong>Cliente:</strong> ' + (pedidoRow.nombre_cliente || '(sin nombre)') + '</p>' +
    '<p><strong>Teléfono:</strong> ' + pedidoRow.telefono + '</p>' +
    '<p><strong>Ciudad:</strong> ' + (pedidoRow.ciudad_envio || '(sin ciudad)') + '</p>' +
    '<p><strong>Dirección:</strong> ' + (pedidoRow.direccion_envio || '(sin dirección)') + '</p>' +
    '<p><strong>Total:</strong> $' + totalDisplay + ' COP</p>' +
    '<p><strong>Pedido WC:</strong> #' + (pedidoRow.woo_order_id || '?') + '</p>' +
    '</div>' +
    '<p style="color:#555">Al confirmar, el pedido pasa a estado <em>procesando</em> en WooCommerce y se notifica al cliente.</p>' +
    '<a href="' + confirmLink + '" style="display:inline-block;background:#2e7d32;color:white;padding:15px 40px;text-decoration:none;border-radius:5px;font-size:18px;font-weight:bold;margin-top:20px">✅ Confirmar pago recibido</a>' +
    '<p style="margin-top:30px;color:#888;font-size:12px">Si no recibiste el pago, cierra esta página sin tocar el botón.</p>' +
    '</body></html>';
  return [{ json: { valido: false, motivo: 'esperando_confirmacion_humana', html } }];
}

return [{ json: { ...pedidoRow, valido: true, auth_woo: 'Basic ' + Buffer.from($env.WOO_CONSUMER_KEY + ':' + $env.WOO_CONSUMER_SECRET).toString('base64') } }];

const pedido = $('¿Continuar?').first().json;
const body = JSON.stringify({
  status: 'processing',
  set_paid: true,
  transaction_id: 'savia-transfer-' + pedido.id,
  meta_data: [
    { key: '_savia_pago_at', value: new Date().toISOString() },
    { key: '_savia_pago_method_final', value: 'transferencia_validada' }
  ]
});
return [{ json: { ...pedido, body_order: body, precio: pedido.total_cop || 0 } }];

const pedido = $('Build WC Order').first().json;
const wcOrder = $('POST WC Order').first().json;
const numeroOrden = (wcOrder && wcOrder.number) || pedido.id;
const nombrePila = (pedido.nombre_cliente || '').split(' ')[0] || '';
const saludo = nombrePila ? nombrePila + ', tu' : 'tu';

const text = 'listo ' + saludo + ' pago quedó confirmado. tu pedido #' + numeroOrden + ' del ' + pedido.producto_nombre + ' ya está en preparación para envío a la dirección que nos diste. en 2-4 días hábiles te llega';

const body = JSON.stringify({ number: pedido.telefono, text });
const instance = pedido.instance || $env.EVOLUTION_INSTANCE_SAVIA || 'dev-router';
return [{ json: { ...pedido, body_cliente: body, instance, numero_orden: numeroOrden } }];

const ctx = $('Build WA Cliente').first().json;
const wcOrder = $('POST WC Order').first().json;
const numeroOrden = (wcOrder && wcOrder.number) || ctx.numero_orden;
const html = '<html><head><meta charset="utf-8"><title>Confirmado</title></head>' +
  '<body style="font-family:sans-serif;padding:40px;max-width:600px;margin:0 auto;text-align:center">' +
  '<h2 style="color:#2e7d32">✅ Pago confirmado</h2>' +
  '<p>Pedido <strong>#' + numeroOrden + '</strong></p>' +
  '<p>Cliente: ' + (ctx.nombre_cliente || '') + '</p>' +
  '<p>Producto: ' + ctx.producto_nombre + '</p>' +
  '<p>Total: $' + Number(ctx.precio || 0).toLocaleString('es-CO') + ' COP</p>' +
  '<hr>' +
  '<p>El pedido se creó en WooCommerce y se notificó al cliente por WhatsApp.</p>' +
  '</body></html>';
return [{ json: { html } }];

const ctx = $('Build WA Cliente').first().json;
const adminPhone = (($env.SAVIA_ADMIN_PHONES || '').split(',')[0] || '').trim().replace(/^\+/, '');
const adminGroup = ($env.SAVIA_ADMIN_GROUP_JID || '').trim();
const adminDestination = adminGroup || adminPhone;
const total = Number(ctx.precio || 0).toLocaleString('es-CO');
const text = '✅ Pedido #' + ctx.numero_orden + ' confirmado\n' +
  'Cliente: ' + (ctx.nombre_cliente || '') + ' — notificado por WhatsApp.\n' +
  'Producto: ' + ctx.producto_nombre + '\n' +
  'Total: $' + total + ' COP\n' +
  'Estado en WC: processing\n' +
  '¡Listo para preparar y despachar! 🌿';
const body = JSON.stringify({ number: adminDestination, text });
const instance = ctx.instance || $env.EVOLUTION_INSTANCE_SAVIA || 'dev-router';
return [{ json: { ...ctx, body_admin: body, admin_phone: adminPhone, instance } }];

